  const candidates=app.snapshot.runs.filter((run)=>run.status==="succeeded"&&run.changeId&&Array.isArray(run.output?.tasks)&&!app.snapshot.tasks.some((task)=>task.sourceRunId===run.id)&&(!scoped||run.workspaceId===workspace?.id)); const loading=scoped?app.workspaceLoading:app.boardLoading; const error=scoped?app.workspaceError:app.boardError; const warnings=projection?.warnings??[]; const toolbar=`<div class="section-toolbar board-toolbar"><div><h1>${scoped?"Workspace Kanban":"统一任务看板"}</h1><p class="muted">CJHX / Jira 可写任务与 GitHub / GitLab 实时只读工作项的统一七状态投影</p></div><div class="header-meta">${scoped&&workspace?`<span class="badge">${esc(workspace.name)}</span>`:""}${candidates.length?`<button class="button secondary" data-action="import-tasks">↓ 导入拆解任务 (${candidates.length})</button>`:""}<button class="button primary" data-action="new-task">＋ 新建任务</button></div></div>`;
  const filters=`<div class="board-filters">${scoped?"":`<label>Workspace<select data-board-filter="workspaceId">${workspaces.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join("")}</select></label>`}<label>来源<select data-board-filter="source"><option value="">全部来源</option><option value="cjhx">CJHX</option><option value="jira">Jira</option><option value="github">GitHub</option><option value="gitlab">GitLab</option></select></label><label>类型<select data-board-filter="kind"><option value="">全部类型</option><option value="task">Task</option><option value="issue">Issue</option><option value="change-request">PR / MR</option></select></label><label>变更<select data-board-filter="changeId">${changes.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join("")}</select></label><label>Owner<select data-board-filter="owner"><option value="">全部 Owner</option>${owners.map((owner)=>`<option value="${esc(owner)}">${esc(owner)}</option>`).join("")}</select></label><label>风险<select data-board-filter="risk"><option value="">全部风险</option>${["L0","L1","L2","L3","L4","L5"].map((risk)=>`<option value="${risk}">${risk}</option>`).join("")}</select></label><label>状态<select data-board-filter="status"><option value="">全部状态</option>${taskColumns.map((column)=>`<option value="${column.status}">${column.label}</option>`).join("")}</select></label><span class="muted">${filtered.length} 个工作项</span></div>`;
