function renderBoardColumn(column:{status:TaskStatus;label:string;hint:string},items:BoardItem[]):string{const matches=items.filter((item)=>item.status===column.status);return `<section class="kanban-column"><header><div><strong>${esc(column.label)}</strong><small>${esc(column.hint)}</small></div><span>${matches.length}</span></header><div class="kanban-cards">${matches.length?matches.map(renderBoardCard).join(""):`<div class="kanban-empty">暂无工作项</div>`}</div></section>`}
function renderBoardCard(item:BoardItem):string{const workspace=app.snapshot.workspaces.find((entry)=>entry.id===item.workspaceId);const sourceLabels:Record<BoardSource,string>={cjhx:"CJHX",jira:"Jira",github:"GitHub",gitlab:"GitLab"};const kindLabels:Record<BoardItemKind,string>={task:"Task",issue:"Issue","change-request":"PR / MR"};const action=item.taskId?`data-task-id="${esc(item.taskId)}"`:item.number&&item.workspaceId?`data-collab-kind="${item.kind}" data-collab-number="${item.number}" data-collab-workspace="${esc(item.workspaceId)}"`:"";return `<article class="task-card board-item-card ${item.writable?"":"read-only"}" role="button" tabindex="0" aria-label="${esc(item.title)}，${esc(taskStatusLabels[item.status])}" ${action}><div class="task-card-meta"><span class="source-badge source-${item.source}">${sourceLabels[item.source]}</span><span class="change-key">${esc(item.reference??kindLabels[item.kind])}</span>${item.priority?`<span class="risk">${esc(item.priority)}</span>`:""}${item.riskLevel?`<span class="risk">${esc(item.riskLevel)}</span>`:""}</div><h3>${esc(item.title)}</h3><p>${esc(workspace?.name??(item.workspaceId?"未知 Workspace":"未关联 Workspace"))} · ${esc(kindLabels[item.kind])}</p>${item.labels.length?`<div class="board-labels">${item.labels.slice(0,3).map((label)=>`<span>${esc(label)}</span>`).join("")}</div>`:""}<div class="task-card-footer"><span>◎ ${esc(item.owner??"unassigned")}</span><span class="${item.writable?"status-success":"muted"}">${item.writable?"可流转":"只读"}</span></div></article>`}
