function modal({ title, description = "", fields, submit = "确认", wide = false, onSubmit }: ModalOptions): void {
  $("#modal-root").innerHTML = `<div class="modal-backdrop"><form class="modal ${wide ? "wide" : ""}"><div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><button type="button" class="icon-button" data-close aria-label="关闭">×</button></div><div class="modal-body"><div class="error-inline"></div><div class="form-grid">${fields}</div></div><div class="modal-footer"><button type="button" class="button ghost" data-close>取消</button><button type="submit" class="button primary">${esc(submit)}</button></div></form></div>`;
  const form = $<HTMLFormElement>("#modal-root form"); const close = () => { $("#modal-root").innerHTML = ""; }; $$('[data-close]', form).forEach((button) => button.addEventListener("click", close)); $(".modal-backdrop").addEventListener("mousedown", (event) => { if (event.target === event.currentTarget) close(); });
  form.addEventListener("submit", async (event) => { event.preventDefault(); const button = $<HTMLButtonElement>('button[type="submit"]', form); const errorBox = $(".error-inline", form); button.disabled = true; errorBox.classList.remove("visible"); try { await onSubmit(new FormData(form)); close(); await refresh({ quiet:true }); } catch (error) { errorBox.textContent = errorMessage(error); errorBox.classList.add("visible"); } finally { button.disabled = false; } }); setTimeout(() => $<HTMLElement>("input,textarea,select", form).focus(), 0);
}
const field = (label: string, name: string, options: FieldOptions = {}): string => `<div class="field ${options.full ? "full" : ""}"><label for="f-${esc(name)}">${esc(label)}</label>${options.type === "textarea" ? `<textarea id="f-${esc(name)}" name="${esc(name)}" class="${options.code ? "code" : ""}" ${options.required ? "required" : ""} placeholder="${esc(options.placeholder || "")}">${esc(options.value || "")}</textarea>` : options.type === "select" ? `<select id="f-${esc(name)}" name="${esc(name)}">${(options.options ?? []).map(([value,text]) => `<option value="${esc(value)}">${esc(text)}</option>`).join("")}</select>` : `<input id="f-${esc(name)}" name="${esc(name)}" type="${esc(options.type || "text")}" value="${esc(options.value || "")}" placeholder="${esc(options.placeholder || "")}" ${options.required ? "required" : ""}>`}${options.help ? `<small>${esc(options.help)}</small>` : ""}</div>`;
