function triggerPipelineModal(pipelineId?:string,kind?:"ci"|"cd"):void{const pipelines=app.devops?.pipelines??[];if(!pipelines.length){toast("没有可触发的流水线",true);return;}const selected=pipelines.find((item)=>itemId(item)===pipelineId)??pipelines[0]!;modal({title:"触发 DevOps 流水线",description:"将向 DevOps 发起真实执行请求；操作必须获得人工审批。",fields:field("流水线","pipelineId",{type:"select",full:true,options:pipelines.map((item):[string,string]=>[itemId(item),`${itemName(item)} · ${String(item.kind??"pipeline").toUpperCase()}`])})+field("执行类型","kind",{type:"select",options:[["ci","CI · 构建验证"],["cd","CD · 部署发布"]]})+field("关联变更","changeId",{type:"select",options:[["","不关联"],...app.snapshot.changes.map((change):[string,string]=>[change.id,`${change.id} · ${change.title}`])]})+field("代码引用","ref",{placeholder:"main / tag / commit"})+field("目标环境","environment",{placeholder:"test / staging / production"})+field("操作人","actor",{required:true,value:selectedChange()?.owner??"release-owner"})+field("执行原因","reason",{required:true,full:true,placeholder:"说明本次 CI/CD 执行目的"})+`<div class="field full"><label class="checkbox"><input type="checkbox" name="approved" value="true"> 已获得本次流水线执行的人工审批</label><small>CI/CD 是外部写操作，未确认审批时后端会拒绝。</small></div>`,submit:"确认触发",onSubmit:async(data)=>{const values=formValues(data);await request("/api/devops/pipelines/trigger",{method:"POST",body:JSON.stringify({...values,approved:values.approved==="true"})});app.devops=null;await loadDevOps();toast(`${String(values.kind).toUpperCase()} 流水线已触发`);}});setTimeout(()=>{$<HTMLSelectElement>('[name="pipelineId"]').value=itemId(selected);$<HTMLSelectElement>('[name="kind"]').value=kind??(selected.kind==="cd"?"cd":"ci");const change=selectedChange();if(change)$<HTMLSelectElement>('[name="changeId"]').value=change.id},0)}
function serviceControlModal(serviceId:string,action:"start"|"stop"|"restart"):void{const service=app.devops?.services.find((item)=>itemId(item)===serviceId);if(!service)return;const actionLabels={start:"启动",stop:"停止",restart:"重启"};modal({title:`${actionLabels[action]}服务`,description:`${itemName(service)} · ${service.environment??"未指定环境"}。该操作将由 DevOps 执行。`,fields:field("服务 ID","serviceId",{required:true,full:true,value:serviceId})+field("目标环境","environment",{value:String(service.environment??"")})+field("操作人","actor",{required:true,value:selectedChange()?.owner??"operator"})+field("操作原因","reason",{required:true,full:true,placeholder:`说明${actionLabels[action]}服务的原因`})+`<div class="field full"><label class="checkbox"><input type="checkbox" name="approved" value="true"> 已获得本次服务${actionLabels[action]}操作的人工审批</label><small>未确认审批时后端会拒绝执行。</small></div>`,submit:`确认${actionLabels[action]}`,onSubmit:async(data)=>{const values=formValues(data);await request("/api/devops/services/control",{method:"POST",body:JSON.stringify({...values,action,approved:values.approved==="true"})});app.devops=null;await loadDevOps();toast(`服务${actionLabels[action]}请求已提交`);}})}
function showRun(id: string): void { const run = app.snapshot.runs.find((item) => item.id === id); if (!run) return; const canImport = run.status === "succeeded" && run.changeId && Array.isArray(run.output?.tasks) && !app.snapshot.tasks.some((task) => task.sourceRunId === run.id); modal({ title: run.skillId ?? run.workflowId ?? "运行详情", description: `${run.id} · ${run.status}`, wide: true, fields: `${canImport ? `<div class="field full"><button type="button" class="button secondary" data-import-run="${esc(run.id)}">↓ 将拆解任务添加到看板</button></div>` : ""}<div class="field full"><label>执行记录</label><pre class="detail-pre">${formatJson(run)}</pre></div>`, submit: "关闭", onSubmit: async () => {} }); const button = document.querySelector<HTMLElement>("[data-import-run]"); button?.addEventListener("click", () => importRunTasks(run.id, run.changeId!)); }
function newTaskModal(): void {
  if (!app.snapshot.changes.length) { toast("请先创建研发变更", true); createChangeModal(); return; } const changeOptions = app.snapshot.changes.map((change): [string,string] => [change.id, `${change.id} · ${change.title}`]);const workspaceOptions=app.snapshot.workspaces.map((item):[string,string]=>[item.id,`${item.name} · ${item.provider}`]);
  modal({ title:"新建本地任务", description:"任务将作为本地草稿保存；发布到 Jira 后状态权威转移至 Jira。", fields:field("关联 Workspace","workspaceId",{type:"select",options:[["","不关联"],...workspaceOptions]})+field("关联变更","changeId",{type:"select",options:changeOptions})+field("Owner","owner",{required:true,value:selectedChange()?.owner??"unassigned"})+field("任务标题","title",{required:true,full:true,placeholder:"实现批量取消接口"})+field("优先级","priority",{type:"select",options:["P0","P1","P2","P3","P4"].map((value):[string,string]=>[value,value])})+field("风险等级","riskLevel",{type:"select",options:["L1","L0","L2","L3","L4","L5"].map((value):[string,string]=>[value,value])})+field("任务说明","description",{type:"textarea",full:true})+field("验收标准","acceptanceCriteria",{type:"textarea",full:true,placeholder:"每行一条验收标准"})+field("依赖任务 ID","dependencies",{full:true,placeholder:"TASK-01, TASK-02"})+field("证据引用","evidenceRefs",{full:true,placeholder:"artifact://report-1, jira://PAY-1"}), submit:"创建任务", onSubmit:async(data)=>{const values=formValues(data);await request("/api/tasks",{method:"POST",body:JSON.stringify({...values,acceptanceCriteria:lines(values.acceptanceCriteria),dependencies:csv(values.dependencies),evidenceRefs:csv(values.evidenceRefs)})});if(app.view==="workspaces"&&app.workspaceView==="kanban")await loadWorkspace();else{app.view="board";await loadBoard()}toast("本地任务已创建");} });
  setTimeout(()=>{const change=selectedChange();if(change)$<HTMLSelectElement>('[name="changeId"]').value=change.id;const scopedWorkspace=app.view==="workspaces"&&app.workspaceView==="kanban"?app.selectedWorkspace:app.boardFilters.workspaceId&&!['unassigned'].includes(app.boardFilters.workspaceId)?app.boardFilters.workspaceId:null;if(scopedWorkspace)$<HTMLSelectElement>('[name="workspaceId"]').value=scopedWorkspace},0);
}
function importTasksModal(): void { const scopedWorkspace=app.view==="workspaces"&&app.workspaceView==="kanban"?app.selectedWorkspace:null;const candidates=app.snapshot.runs.filter((run)=>run.status==="succeeded"&&run.changeId&&Array.isArray(run.output?.tasks)&&!app.snapshot.tasks.some((task)=>task.sourceRunId===run.id)&&(!scopedWorkspace||run.workspaceId===scopedWorkspace));if(!candidates.length){toast("没有待导入的需求拆解运行",true);return;}modal({title:"导入需求拆解任务",description:"导入操作幂等；每个运行只会生成一组本地草稿。",fields:field("Skill Run","runId",{type:"select",full:true,options:candidates.map((run):[string,string]=>[run.id,`${run.changeId} · ${run.id}`])}),submit:"添加到看板",onSubmit:async(data)=>{const runId=formValues(data).runId??"";const run=candidates.find((item)=>item.id===runId);if(!run?.changeId)throw new Error("运行未关联研发变更");await request(`/api/runs/${encodeURIComponent(run.id)}/tasks/import`,{method:"POST",body:JSON.stringify({changeId:run.changeId})});if(app.view==="workspaces"&&app.workspaceView==="kanban")await loadWorkspace();else{app.view="board";await loadBoard()}toast("拆解任务已添加到看板");}}); }
async function importRunTasks(runId:string,changeId:string):Promise<void>{try{await request(`/api/runs/${encodeURIComponent(runId)}/tasks/import`,{method:"POST",body:JSON.stringify({changeId})});$("#modal-root").innerHTML="";app.view="board";await refresh({quiet:true});await loadBoard();toast("拆解任务已添加到看板");}catch(error){toast(errorMessage(error),true)}}
function taskDetailModal(taskId:string):void{const task=app.snapshot.tasks.find((item)=>item.id===taskId);if(!task)return;const transitions=taskColumns.filter((column)=>taskTransitions[task.status].includes(column.status));const criteria=task.acceptanceCriteria.length?`<ul>${task.acceptanceCriteria.map((item)=>`<li>${esc(item)}</li>`).join("")}</ul>`:"未填写";const deps=task.dependencies.length?task.dependencies.map(esc).join("、"):"无";const source=task.sourceRunId?`<button type="button" class="button ghost" data-open-run="${esc(task.sourceRunId)}">${esc(task.sourceRunId)}</button>`:"手工创建";const publish=task.authority==="local-draft"?`<button type="button" class="button secondary" data-task-publish ${app.snapshot.integrations.jiraConfigured?"":"disabled"}>发布到 Jira</button>`:`<button type="button" class="button secondary" data-task-sync>同步 Jira 状态</button>`;modal({title:task.title,description:`${task.changeId} · ${taskStatusLabels[task.status]} · ${task.authority==="jira"?task.jiraIssueKey:"本地草稿"}`,wide:true,fields:`<div class="task-detail-grid field full"><section><label>验收标准</label><div class="task-detail-copy">${criteria}</div></section><section><label>依赖</label><div class="task-detail-copy">${deps}</div></section><section><label>证据引用</label><div class="task-detail-copy">${task.evidenceRefs.length?task.evidenceRefs.map(esc).join("、"):"暂无"}</div></section><section><label>来源运行</label><div>${source}</div></section></div><div class="field"><label>目标状态</label><select name="targetStatus">${transitions.map((item)=>`<option value="${item.status}">${item.label}</option>`).join("")}</select></div>${field("执行人","taskActor",{required:true,value:task.owner})}${field("转换原因","taskReason",{required:true,full:true,value:"任务状态已更新"})}<div class="field full"><label class="checkbox"><input type="checkbox" name="taskApproved" value="true"> 已批准 Jira 发布或状态写回</label><small>${app.snapshot.integrations.jiraConfigured?"Jira 写操作必须显式审批。":"当前未配置 Jira Adapter；可继续使用本地草稿状态。"}</small></div><div class="field full task-detail-actions"><button type="button" class="button primary" data-task-transition>更新状态</button>${publish}</div>`,submit:"关闭",onSubmit:async()=>{}});const root=$("#modal-root");root.addEventListener("click",(event)=>{const target=event.target instanceof Element?event.target.closest<HTMLElement>("button"):null;if(!target)return;if(target.dataset.openRun){$("#modal-root").innerHTML="";showRun(target.dataset.openRun)}else if(target.hasAttribute("data-task-transition")){void mutateTask(task,"transition")}else if(target.hasAttribute("data-task-publish")){void mutateTask(task,"publish")}else if(target.hasAttribute("data-task-sync")){void mutateTask(task,"sync")}});}
async function mutateTask(task:Task,action:"transition"|"publish"|"sync"):Promise<void>{try{if(action==="transition"){const target=$<HTMLSelectElement>('[name="targetStatus"]').value as TaskStatus;await request(`/api/tasks/${encodeURIComponent(task.id)}/transitions`,{method:"POST",body:JSON.stringify({target,actor:$<HTMLInputElement>('[name="taskActor"]').value,reason:$<HTMLInputElement>('[name="taskReason"]').value,approved:$<HTMLInputElement>('[name="taskApproved"]').checked})})}else if(action==="publish"){const approved=$<HTMLInputElement>('[name="taskApproved"]').checked;await request(`/api/tasks/${encodeURIComponent(task.id)}/jira/publish`,{method:"POST",body:JSON.stringify({approved})})}else await request(`/api/tasks/${encodeURIComponent(task.id)}/jira/sync`,{method:"POST",body:"{}"});$("#modal-root").innerHTML="";await refresh({quiet:true});if(app.view==="board")await loadBoard();else if(app.view==="workspaces"&&app.workspaceView==="kanban")await loadWorkspace();toast(action==="sync"?"Jira 状态已同步":"任务已更新")}catch(error){const box=$(".error-inline");box.textContent=errorMessage(error);box.classList.add("visible")}}
async function activateSourceControl(provider:"gitlab"|"github"):Promise<void>{try{await request(`/api/${provider}/config/activate`,{method:"POST",body:"{}"});await refresh({quiet:true});toast(`${provider==="gitlab"?"GitLab":"GitHub"} 已设为当前代码托管 Adapter`)}catch(error){toast(errorMessage(error),true)}}
function lines(value:string|undefined):string[]{return(value??"").split("\n").map((item)=>item.trim()).filter(Boolean)}function csv(value:string|undefined):string[]{return(value??"").split(",").map((item)=>item.trim()).filter(Boolean)}

$<HTMLInputElement>("#change-search").addEventListener("input", renderChangeList); $("#new-change").addEventListener("click", createChangeModal); $("#theme-toggle").addEventListener("click", () => { document.documentElement.classList.toggle("dark"); localStorage.setItem("cjhx:theme", document.documentElement.classList.contains("dark") ? "dark" : "light"); });
if (localStorage.getItem("cjhx:theme") === "dark" || (!localStorage.getItem("cjhx:theme") && matchMedia("(prefers-color-scheme: dark)").matches)) document.documentElement.classList.add("dark");
$$<HTMLElement>(".nav-item").forEach((item) => item.addEventListener("click", () => { const view = item.dataset.view; if (view === "workspaces" || view === "changes" || view === "board" || view === "devops" || view === "integrations" || view === "skills" || view === "runs") { app.view = view; render(); if(view==="workspaces"&&!app.workspaceLoading)void loadWorkspace();if(view==="board"&&!app.boardLoading)void loadBoard();if(view==="devops"&&!app.devops&&!app.devopsLoading)void loadDevOps(); } })); $("#primary-action").addEventListener("click", () => app.view === "workspaces" ? importWorkspaceModal() : app.view === "changes" ? createChangeModal() : app.view === "board" ? newTaskModal() : app.view === "devops" ? triggerPipelineModal() : app.view === "integrations" ? jiraConfigModal() : app.view === "skills" ? installSkillModal() : runWorkflowModal()); $("#install-skill").addEventListener("click", installSkillModal);
$("#change-list").addEventListener("click", (event) => { const row = event.target instanceof Element ? rowWithData(event.target, "[data-change-id]") : null; const id = row?.dataset.changeId; if (id) { app.selectedChange = id; app.view = "changes"; localStorage.setItem("cjhx:selected-change", id); render(); } });
$("#content").addEventListener("change", (event) => { const select = event.target instanceof HTMLSelectElement ? event.target : null;if(select?.hasAttribute("data-workspace-select")){app.selectedWorkspace=select.value;localStorage.setItem("cjhx:selected-workspace",select.value);app.workspacePath="";app.workspaceData={};void loadWorkspace();return} const filter = select?.dataset.boardFilter;if(select&&filter&&["workspaceId","source","kind","changeId","owner","risk","status"].includes(filter)){app.boardFilters[filter as BoardFilter]=select.value;if(app.view==="board")renderBoard();else renderWorkspaces();}else if(select?.dataset.devopsFilter==="changeId"){app.devopsChangeId=select.value;app.devops=null;void loadDevOps()} });
$("#content").addEventListener("click", (event) => { const target = event.target instanceof Element ? rowWithData(event.target, "button,[data-run-id],[data-task-id],[data-collab-kind]") : null; if (!target) return;if(target.dataset.deleteRef&&(target.dataset.refType==="branch"||target.dataset.refType==="tag")){void deleteRef(target.dataset.deleteRef,target.dataset.refType);return}if(target.dataset.ref){const workspace=selectedWorkspace();if(workspace)void request<WorkspaceCommit[]>(`/api/workspaces/${encodeURIComponent(workspace.id)}/commits?ref=${encodeURIComponent(target.dataset.ref)}`).then((commits)=>{app.workspaceData.commits=commits;renderWorkspaces()}).catch((error:unknown)=>toast(errorMessage(error),true));return}if(target.dataset.workspaceView&&  (target.dataset.workspaceView==="overview"||target.dataset.workspaceView==="kanban"||target.dataset.workspaceView==="sessions"||target.dataset.workspaceView==="team"||target.dataset.workspaceView==="codebase")){app.workspaceView=target.dataset.workspaceView;app.workspacePath="";void loadWorkspace();return}if(target.dataset.treePath!==undefined){app.workspacePath=target.dataset.treePath;delete app.workspaceData.file;delete app.workspaceData.search;void loadWorkspace();return}if(target.dataset.filePath){void openWorkspaceFile(target.dataset.filePath);return}if(target.dataset.commitSha){void inspectWorkspaceCommit(target.dataset.commitSha);return}if(target.dataset.collabKind&&target.dataset.collabNumber&&(target.dataset.collabKind==="issue"||target.dataset.collabKind==="change-request")){void showCollaborationComments(target.dataset.collabKind,Number(target.dataset.collabNumber),target.dataset.collabWorkspace);return}if(target.dataset.removeWorktree){const workspace=selectedWorkspace();if(workspace&&confirm(`移除 Worktree ${target.dataset.removeWorktree}？`))void request(`/api/workspaces/${encodeURIComponent(workspace.id)}/worktrees/remove`,{method:"POST",body:JSON.stringify({path:target.dataset.removeWorktree,approved:true})}).then(()=>loadWorkspace()).catch((error:unknown)=>toast(errorMessage(error),true));return} const tab = target.dataset.tab; if (tab === "evidence" || tab === "tasks" || tab === "history" || tab === "runs") { app.evidenceTab = tab; renderChange(); } else if (target.dataset.taskId) taskDetailModal(target.dataset.taskId); else if (target.dataset.transition && lifecycle.includes(target.dataset.transition as LifecycleState)) transitionModal(target.dataset.transition as LifecycleState); else if (target.dataset.runSkill) runSkillModal(target.dataset.runSkill); else if (target.dataset.runId) showRun(target.dataset.runId); else if(target.dataset.pipelineId)triggerPipelineModal(target.dataset.pipelineId,target.dataset.pipelineKind==="cd"?"cd":"ci");else if(target.dataset.serviceId&&(target.dataset.serviceAction==="start"||target.dataset.serviceAction==="stop"||target.dataset.serviceAction==="restart"))serviceControlModal(target.dataset.serviceId,target.dataset.serviceAction);else { const actions: Record<string, () => void> = { "import-workspace":importWorkspaceModal,"remove-workspace":()=>{void removeWorkspace()},"refresh-workspace":()=>{void loadWorkspace()},"add-worktree":addWorktreeModal,"create-ref":createRefModal,"new-change": createChangeModal, "new-task": newTaskModal, "import-tasks": importTasksModal, "add-evidence": addEvidenceModal, "install-skill": installSkillModal, "run-skill": () => runSkillModal(), "run-workflow": runWorkflowModal, "refresh-devops":()=>{void loadDevOps()}, "trigger-pipeline":()=>triggerPipelineModal(), "configure-devops":devOpsConfigModal, "configure-jira":jiraConfigModal, "configure-gitlab":gitLabConfigModal, "configure-github":gitHubConfigModal, "activate-gitlab":()=>{void activateSourceControl("gitlab")}, "activate-github":()=>{void activateSourceControl("github")} }; const action = target.dataset.action; if (action) actions[action]?.(); } });
$("#content").addEventListener("submit",(event)=>{const form=event.target instanceof HTMLFormElement?event.target:null;if(!form?.hasAttribute("data-code-search"))return;event.preventDefault();const workspace=selectedWorkspace();const query=formValues(new FormData(form)).query;if(!workspace||!query)return;void request<WorkspaceData["search"]>(`/api/workspaces/${encodeURIComponent(workspace.id)}/search?q=${encodeURIComponent(query)}`).then((results)=>{app.workspaceData.search=results;delete app.workspaceData.file;renderWorkspaces()}).catch((error:unknown)=>toast(errorMessage(error),true))});
$("#content").addEventListener("keydown", (event) => { if (event.key !== "Enter" && event.key !== " ") return; const target = event.target instanceof Element ? rowWithData(event.target, "[data-task-id],[data-collab-kind]") : null; if (target?.dataset.taskId) { event.preventDefault(); taskDetailModal(target.dataset.taskId); } else if(target?.dataset.collabKind&&target.dataset.collabNumber&&(target.dataset.collabKind==="issue"||target.dataset.collabKind==="change-request")){event.preventDefault();void showCollaborationComments(target.dataset.collabKind,Number(target.dataset.collabNumber),target.dataset.collabWorkspace)} });
function rowWithData(target: Element, selector: string): HTMLElement | null { const row = target.closest(selector); return row instanceof HTMLElement ? row : null; }
document.addEventListener("keydown", (event) => { const mod = navigator.userAgent.includes("Mac") ? event.metaKey : event.ctrlKey; if (mod && event.key.toLowerCase() === "k") { event.preventDefault(); $<HTMLInputElement>("#change-search").focus(); } if (event.key === "Escape" && $("#modal-root").children.length) $("#modal-root").innerHTML = ""; }); $("#search-key").textContent = navigator.userAgent.includes("Mac") ? "⌘K" : "Ctrl+K";
void (async()=>{await refresh();await loadBoard();if(app.selectedWorkspace)await loadWorkspace()})(); setInterval(() => void (async()=>{await refresh({quiet:true});if(app.view==="board"&&!app.boardLoading)await loadBoard();if(app.view==="workspaces"&&app.workspaceView==="kanban"&&!app.workspaceLoading)await loadWorkspace();if(app.view==="devops"&&app.snapshot.integrations.devopsConfigured&&!app.devopsLoading)await loadDevOps()})(), 15000);
